#include <iostream>
#include <sstream>
#include <stdexcept>
#include <vector>
int main() {
    std::istringstream input("6 4");
    std::vector<int> values;
    int value = 0;
    // Suitable for this fixed input, not a complete token grammar.
    while (input >> value) values.push_back(value);
    if (values.empty() || values.size() > 1000)
        throw std::invalid_argument("count");
    for (int n : values) {
        if (n < -100 || n > 100)
            throw std::invalid_argument("range");
    }
    int total = 0;
    for (int n : values) total += n;
    std::cout << "count=" << values.size()
              << " total=" << total << '\n';
}

#include <charconv>
#include <iostream>
#include <string>
int main() {
    const std::string token = "6x";
    int value = 0;
    const char* end = token.data() + token.size();
    const auto result = std::from_chars(token.data(), end, value);
    // Success of a prefix is weaker than success of the token.
    const bool prefix_ok = result.ec == std::errc{};
    const bool whole_ok = prefix_ok && result.ptr == end;
    std::cout << std::boolalpha;
    std::cout << "prefix=" << value << " conversion=" << prefix_ok << '\n';
    std::cout << "whole token=" << whole_ok << '\n';
    std::cout << (whole_ok ? "accepted" : "rejected") << '\n';
}
